SELECT A.RPT_ID, A.BRD_NO, A.BRD_TITL_NM, A.MBR_CD, A.BRD_PBLS_DTM, A.RPT_CODE, A.RPT_TARGET_ID, A.RPT_STATUS_CODE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY B.BRD_PBLS_DTM DESC) AS RNUM, B.BRD_NO, B.BRD_TITL_NM, B.MBR_CD, B.BRD_PBLS_DTM, R.RPT_ID, R.RPT_CODE, R.RPT_TARGET_ID, R.RPT_STATUS_CODE FROM BOARD B JOIN REPORT R ON B.BRD_NO = R.BRD_NO WHERE 1=1 AND R.RPT_DEL_YN = 'N' AND B.BRD_DEL_YN = 'N'
AND R.RPT_CODE = #{detailSearch.searchRptCode}
AND R.RPT_CODE = 'MEMB'
AND B.BRD_TITL_NM LIKE '%' || #{detailSearch.searchTitle} || '%'
AND B.MBR_CD LIKE '%' || #{detailSearch.searchWriter} || '%'
AND R.RPT_TARGET_ID LIKE '%' || #{detailSearch.searchReportedTargetId} || '%'
AND R.RPT_STATUS_CODE = #{detailSearch.searchRptStatusCode}
AND B.BRD_PBLS_DTM >= #{detailSearch.brdPblsDtmFrom, jdbcType=DATE}
AND B.BRD_PBLS_DTM < #{detailSearch.brdPblsDtmTo, jdbcType=DATE}
AND ( B.BRD_TITL_NM LIKE '%' || #{simpleSearch.searchWord} || '%' OR B.BRD_CONT LIKE '%' || #{simpleSearch.searchWord} || '%' )
) A WHERE RNUM BETWEEN #{firstRecordIndex} AND #{lastRecordIndex}

SELECT COUNT(*) FROM BOARD B JOIN REPORT R ON B.BRD_NO = R.BRD_NO WHERE 1=1 AND R.RPT_DEL_YN = 'N' AND B.BRD_DEL_YN = 'N'
AND R.RPT_CODE = #{detailSearch.searchRptCode}
AND R.RPT_CODE = 'MEMB'
AND B.BRD_TITL_NM LIKE '%' || #{detailSearch.searchTitle} || '%'
AND B.MBR_CD LIKE '%' || #{detailSearch.searchWriter} || '%'
AND R.RPT_TARGET_ID LIKE '%' || #{detailSearch.searchReportedTargetId} || '%'
AND R.RPT_STATUS_CODE = #{detailSearch.searchRptStatusCode}
AND B.BRD_PBLS_DTM >= #{detailSearch.brdPblsDtmFrom, jdbcType=DATE}
AND B.BRD_PBLS_DTM < #{detailSearch.brdPblsDtmTo, jdbcType=DATE}
AND ( B.BRD_TITL_NM LIKE '%' || #{simpleSearch.searchWord} || '%' OR B.BRD_CONT LIKE '%' || #{simpleSearch.searchWord} || '%' )

mapper.update:
UPDATE REPORT
SET
    RPT_STATUS_CODE = #{rptStatusCode}
WHERE
    RPT_ID = #{rptId}

UPDATE MEMBER
SET MBR_STATUS_CODE = #{mbrStatus}
WHERE MBR_ID = #{mbrId}
